-- Cluster PostgreSQL descartável: não simula upload HTTP ou iPhone.
begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000008001'),('00000000-0000-4000-8000-000000008002'),('00000000-0000-4000-8000-000000008003');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008001';
select public.create_business('Retrato local','profile-image-test','autonomo','mundo-novo-ms') as bid \gset
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008101');
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008101');
select test.assert_true((select count(*)=1 from public.business_profile_images),'preparação idempotente');
select test.assert_true((select count(*)=0 from public.portfolio_items),'retrato nunca entra no portfólio');
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008101'),'22023','sem objeto não finaliza nem troca avatar');
select test.expect_error(format('update public.businesses set profile_avatar_path=%L where id=%L',:'bid'||'/profile/00000000-0000-4000-8000-000000008101.webp',:'bid'),'42501','ponteiro novo não pode ser forjado pelo frontend');
select test.expect_error('update public.business_profile_images set media_state=''ready''','42501','não forja estado ready');
select test.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('business-profile','sem-metadados.webp','{}')$q$,'23503','objeto exige metadado pendente');
insert into storage.objects(bucket_id,name,metadata) values('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008101.webp','{"mimetype":"image/webp","size":1024}');
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008101');
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008101');
select test.assert_true((select profile_avatar_path=:'bid'||'/profile/00000000-0000-4000-8000-000000008101.webp' from businesses where id=:'bid'),'finalização aponta para objeto pronto');
select test.assert_true((select status='draft' from businesses where id=:'bid'),'não publica negócio');
select test.assert_true((select count(*)=0 from business_subscriptions),'não inicia gratuidade');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008002';
select test.expect_error(format('select public.admin_profile_photo(%L)',:'bid'),'42501','revisão do retrato exige administrador da plataforma');
select test.assert_true((select count(*)=0 from public.business_profile_images),'terceiro não lê retrato draft');
select test.assert_true((select count(*)=0 from storage.objects where bucket_id='business-profile'),'terceiro não lê objeto draft');
select test.expect_error(format('select public.profile_photo_command(''prepare'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008102'),'42501','terceiro não cria retrato para outro negócio');
set local role anon;
select test.assert_true((select count(*)=0 from storage.objects where bucket_id='business-profile'),'anônimo não lê retrato draft');
select test.expect_error('select expected_avatar_path from public.business_profile_images','42501','snapshot de substituição não é coluna pública');
reset role;
insert into business_members(business_id,user_id,role) values(:'bid','00000000-0000-4000-8000-000000008003','admin');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008003';
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008102',:'bid'||'/profile/00000000-0000-4000-8000-000000008101.webp');
insert into storage.objects(bucket_id,name,metadata) values('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008102.webp','{"mimetype":"image/png","size":1024}');
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008102'),'22023','MIME incorreto não altera foto anterior');
select test.assert_true((select profile_avatar_path like '%8101.webp' from businesses where id=:'bid'),'foto anterior preservada após falha');
reset role;
update storage.objects set metadata='{"mimetype":"image/webp","size":5242881}' where name like '%8102.webp';
set local role authenticated;
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008102'),'22023','limite validado na finalização');
reset role;
update storage.objects set metadata='{"mimetype":"image/webp","size":1024}' where name like '%8102.webp';
set local role authenticated;
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008102');
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008101'),'40001','repetição obsoleta não restaura foto anterior');
select test.expect_error(format('select public.profile_photo_command(''prepare'',%L,%L,null)',:'bid','00000000-0000-4000-8000-000000008103'),'40001','seleção obsoleta não sobrescreve mudança concorrente');
-- Publicação só em SQL no cluster descartável, sem simular aprovação operacional.
reset role;
update businesses set status='published' where id=:'bid';
set local role anon;
select test.assert_true((select count(*)=1 from storage.objects where bucket_id='business-profile'),'público só lê retrato atual do negócio publicado');
select test.assert_true((select count(*)=0 from storage.objects where name like '%8101.webp'),'foto substituída continua privada');
reset role;
update businesses set status='draft' where id=:'bid';
insert into private.platform_admins(user_id) values('00000000-0000-4000-8000-000000008002');
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008002';
select test.assert_true(public.admin_profile_photo(:'bid') like '%8102.webp','RPC de revisão retorna apenas retrato atual');
select test.assert_true((select count(*)=2 from public.business_profile_images),'administrador da plataforma consegue revisar retratos prontos em draft');
select test.expect_error(format('select public.profile_photo_command(''remove'',%L,null,%L)',:'bid',:'bid'||'/profile/00000000-0000-4000-8000-000000008102.webp'),'42501','administrador da plataforma não substitui responsável do negócio');
select test.assert_true(not has_column_privilege('authenticated','public.businesses','status','UPDATE'),'publicação permanece protegida');
-- Duas escolhas para o mesmo ponteiro: somente a primeira finalização vence.
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008001';
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008104',:'bid'||'/profile/00000000-0000-4000-8000-000000008102.webp');
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008105',:'bid'||'/profile/00000000-0000-4000-8000-000000008102.webp');
insert into storage.objects(bucket_id,name,metadata) values
('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008104.webp','{"mimetype":"image/webp","size":1024}'),
('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008105.webp','{"mimetype":"image/webp","size":1024}');
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008104');
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008105'),'40001','segunda seleção obsoleta não substitui vencedora');
select test.assert_true((select profile_avatar_path like '%8104.webp' from businesses where id=:'bid'),'ponteiro vencedor preservado');
select test.assert_true((select count(*)=0 from portfolio_items),'nenhum retrato entrou na grade de trabalhos');
-- Compatibilidade real SQL com a escolha direta feita por #34/#35.
select test.assert_true(has_column_privilege('authenticated','public.businesses','avatar_path','UPDATE'),'grant legado preservado na expansão');
select public.portfolio_command('prepare',:'bid','00000000-0000-4000-8000-000000008211');
select public.portfolio_command('prepare',:'bid','00000000-0000-4000-8000-000000008212');
insert into storage.objects(bucket_id,name,metadata) values
('business-portfolio',:'bid'||'/portfolio/00000000-0000-4000-8000-000000008211.webp','{"mimetype":"image/webp","size":1024}'),
('business-portfolio',:'bid'||'/portfolio/00000000-0000-4000-8000-000000008212.webp','{"mimetype":"image/webp","size":1024}');
select public.portfolio_command('finalize',:'bid','00000000-0000-4000-8000-000000008211');
select public.portfolio_command('finalize',:'bid','00000000-0000-4000-8000-000000008212');
update businesses set avatar_path=:'bid'||'/portfolio/00000000-0000-4000-8000-000000008211.webp' where id=:'bid';
select test.assert_true((select profile_avatar_path is null and avatar_path like '%8211.webp' from businesses where id=:'bid'),'seleção legada válida continua funcionando e passa a ser efetiva');
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008107',:'bid'||'/portfolio/00000000-0000-4000-8000-000000008211.webp');
insert into storage.objects(bucket_id,name,metadata) values('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008107.webp','{"mimetype":"image/webp","size":1024}');
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008107');
select test.assert_true((select avatar_path like '%8211.webp' and profile_avatar_path like '%8107.webp' from businesses where id=:'bid'),'retrato novo mantém fallback legível por #34/#35');
reset role;
update businesses set status='published' where id=:'bid';
set local role anon;
select test.assert_true((select avatar_path like '%8211.webp' from public.search_public_businesses('','','','',1) where id=:'bid'),'RPC antiga continua retornando bucket legado');
select test.assert_true((select avatar_path like '%8107.webp' from public.search_public_businesses_profile('','','','',1) where id=:'bid'),'RPC nova retorna retrato separado sem alterar filtros');
reset role;
update businesses set status='draft' where id=:'bid';
set local role authenticated;
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000008001';
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008108',:'bid'||'/profile/00000000-0000-4000-8000-000000008107.webp');
update businesses set avatar_path=:'bid'||'/portfolio/00000000-0000-4000-8000-000000008212.webp' where id=:'bid';
select test.expect_error(format('select public.profile_photo_command(''finalize'',%L,%L)',:'bid','00000000-0000-4000-8000-000000008108'),'40001','troca legada concorrente impede finalização obsoleta');
select test.expect_error(format('update businesses set avatar_path=%L where id=%L',:'bid'||'/profile/00000000-0000-4000-8000-000000008107.webp',:'bid'),'23514','cliente antigo não aponta para bucket novo');
select test.expect_error(format('update businesses set avatar_path=%L where id=%L',:'bid'||'/portfolio/00000000-0000-4000-8000-000000008299.webp',:'bid'),'23514','cliente antigo não forja foto sem metadados prontos');
select public.profile_photo_command('prepare',:'bid','00000000-0000-4000-8000-000000008109',:'bid'||'/portfolio/00000000-0000-4000-8000-000000008212.webp');
insert into storage.objects(bucket_id,name,metadata) values('business-profile',:'bid'||'/profile/00000000-0000-4000-8000-000000008109.webp','{"mimetype":"image/webp","size":1024}');
select public.profile_photo_command('finalize',:'bid','00000000-0000-4000-8000-000000008109');
select public.profile_photo_command('clear_legacy',:'bid',null,:'bid'||'/portfolio/00000000-0000-4000-8000-000000008212.webp');
select test.assert_true((select avatar_path is null and profile_avatar_path like '%8109.webp' from businesses where id=:'bid'),'limpar fallback ao excluir trabalho não apaga retrato');
select test.assert_true((select status='draft' from businesses where id=:'bid'),'compatibilidade não publica negócio');
select test.assert_true((select count(*)=0 from business_subscriptions),'compatibilidade não inicia gratuidade');
rollback;
